6	// ---------- unwrap: collapse a wrapped file back to one logical line per unit
7	const unwrap = (text) => {
8	  const out = [];
9	  let cur = null;
10	  const flush = () => { if (cur !== null) { out.push(cur); cur = null; } };
11	  for (const raw of text.split('\n')) {
12	    if (!raw.trim()) { flush(); out.push(''); continue; }
13	    if (/^#/.test(raw)) { flush(); out.push(raw); continue; }
14	    if (/^- /.test(raw)) { flush(); cur = raw; continue; }
15	    if (/^\d+\. /.test(raw)) { flush(); cur = raw; continue; }
16	    if (cur === null) cur = raw;
17	    else cur += ' ' + raw.trim();
18	  }
19	  flush();
20	  // collapse runs of blank lines
21	  return out.filter((l, i) => l !== '' || out[i - 1] !== '');
22	};
