24	// ---------- wrap: break a logical line at LIMIT bytes without splitting atoms
25	const tokenize = (text) => {
26	  const out = [];
27	  const atom = /`[^`]*`|\[[^\]]*\]\([^)]*\)/g;
28	  let last = 0;
29	  for (const m of text.matchAll(atom)) {
30	    if (m.index < last) continue;
31	    out.push(...text.slice(last, m.index).split(' ').filter(Boolean));
32	    const before = out.length && !/\s$/.test(text.slice(0, m.index)) ? out.pop() : '';
33	    const tail = text.slice(m.index + m[0].length).match(/^[^\s]+/);
34	    const after = tail ? tail[0] : '';
35	    last = m.index + m[0].length + after.length;
36	    out.push(before + m[0] + after);
37	  }
38	  out.push(...text.slice(last).split(' ').filter(Boolean));
39	  return out;
40	};
