42	const wrap = (body, first, cont) => {
43	  const lines = [];
44	  let line = first;
45	  let fresh = true;
46	  for (const tok of tokenize(body)) {
47	    if (!fresh && Buffer.byteLength(line + ' ' + tok) > LIMIT) {
48	      lines.push(line);
49	      line = cont + tok;
50	    } else {
51	      line = fresh ? line + tok : line + ' ' + tok;
